def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    strings = []
    for _ in range(N):
        s = input[idx]
        c = int(input[idx+1])
        strings.append((s, c))
        idx += 2

    heap = []
    heapq.heappush(heap, (0, ""))
    visited = {"" : 0}

    while heap:
        cost, current = heapq.heappop(heap)
        if current and current == current[::-1]:
            print(cost)
            return
        for s, c in strings:
            new_str = current + s
            new_cost = cost + c
            if new_str not in visited or new_cost < visited[new_str]:
                visited[new_str] = new_cost
                heapq.heappush(heap, (new_cost, new_str))
    print(-1)

