    # Check for pairs of strings
    for i in range(N):
        for j in range(N):
            s1 = strings[i]
            s2 = strings[j]
            if is_pal(s1 + s2) or is_pal(s2 + s1):
                total = costs[i] + costs[j]
                if total < min_cost:
                    min_cost = total

    # Check for triplets of strings
    for i in range(N):
        for j in range(N):
            for k in range(N):
