import sys

def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = []
    for _ in range(H):
        row = list(map(int, sys.stdin.readline().split()))
        grid.append(row)

    odd_cells = []
    for y in range(H):
        for x in range(W):
            if grid[y][x] % 2 == 1:
                odd_cells.append((y + 1, x + 1))

    steps = []

    def get_steps(A, B):
        steps = []
        y1, x1 = A
        y2, x2 = B

        while x1 != x2:
            if x1 < x2:
                steps.append((y1, x1, y1, x1 + 1))
                x1 += 1
            else:
                steps.append((y1, x1, y1, x1 - 1))
                x1 -= 1

        while y1 != y2:
            if y1 < y2:
                steps.append((y1, x1, y1 + 1, x1))
                y1 += 1
            else:
                steps.append((y1, x1, y1 - 1, x1))
                y1 -= 1

        return steps

    if len(odd_cells) % 2 == 0:
        for i in range(0, len(odd_cells), 2):
            a = odd_cells[i]
            b = odd_cells[i + 1]
            steps.extend(get_steps(a, b))
    else:
        for i in range(1, len(odd_cells), 2):
            a = odd_cells[i]
            b = odd_cells[i + 1]
            steps.extend(get_steps(a, b))

    print(len(steps))
    for step in steps:
        print(f"{step[0]} {step[1]} {step[2]} {step[3]}")

