import sys

def main():
    H, W = map(int, sys.stdin.readline().split())
    a = []
    for _ in range(H):
        a.append(list(map(int, sys.stdin.readline().split())))
    parity = [[x % 2 for x in row] for row in a]
    operations = []
    for i in range(H):
        for j in range(W):
            if parity[i][j] == 1:
                if j < W - 1:
                    # Move right
                    new_i, new_j = i, j + 1
                    operations.append((i+1, j+1, i+1, j+2))
                    parity[i][j] ^= 1
                    parity[new_i][new_j] ^= 1
                elif i < H - 1:
                    # Move down
                    new_i, new_j = i + 1, j
                    operations.append((i+1, j+1, i+2, j+1))
                    parity[i][j] ^= 1
                    parity[new_i][new_j] ^= 1
                else:
                    # Move up or left
                    if i > 0:
                        # Move up
                        new_i, new_j = i - 1, j
                        operations.append((i+1, j+1, i, j+1))
                        parity[i][j] ^= 1
                        parity[new_i][new_j] ^= 1
                    else:
                        if j > 0:
                            # Move left
                            new_i, new_j = i, j - 1
                            operations.append((i+1, j+1, i+1, j))
                            parity[i][j] ^= 1
                            parity[new_i][new_j] ^= 1
    print(len(operations))
    for op in operations:
        print(' '.join(map(str, op)))

