from functools import lru_cache

def main():
    N, K = map(int, sys.stdin.readline().split())
    A = list(map(int, sys.stdin.readline().split()))

    max_bit = 60  # since K can be up to 1e12, which is less than 2^40, 60 is safe
    count_0 = [0] * (max_bit + 1)
    count_1 = [0] * (max_bit + 1)

    for j in range(max_bit + 1):
        cnt0 = 0
        for a in A:
            if (a >> j) & 1 == 0:
                cnt0 += 1
        count_0[j] = cnt0
        count_1[j] = N - cnt0

    @lru_cache(maxsize=None)
    def dp(pos, tight):
        if pos == -1:
            return 0
        k_bit = (K >> pos) & 1
        max_sum = 0
        for b in [0, 1]:
            if tight:
