MOD = 998244353

def main():
    N, K = map(int, sys.stdin.readline().split())
    matrix = [list(map(int, sys.stdin.readline().split())) for _ in range(N)]

    # Build row adjacency list
    adj_rows = [[] for _ in range(N)]
    for i in range(N):
        for j in range(i + 1, N):
            valid = True
            for c in range(N):
                if matrix[i][c] + matrix[j][c] > K:
                    valid = False
                    break
            if valid:
                adj_rows[i].append(j)
                adj_rows[j].append(i)

    # Find row components
    visited_rows = [False] * N
    row_components = []
    for i in range(N):
        if not visited_rows[i]:
            q = deque()
            q.append(i)
            visited_rows[i] = True
            component = []
            while q:
                node = q.popleft()
                component.append(node)
                for neighbor in adj_rows[node]:
                    if not visited_rows[neighbor]:
                        visited_rows[neighbor] = True
                        q.append(neighbor)
            row_components.append(component)

    # Build column adjacency list
    adj_cols = [[] for _ in range(N)]
    for x in range(N):
        for y in range(x + 1, N):
            valid = True
            for r in range(N):
                if matrix[r][x] + matrix[r][y] > K:
                    valid = False
                    break
            if valid:
                adj_cols[x].append(y)
                adj_cols[y].append(x)

    # Find column components
    visited_cols = [False] * N
    col_components = []
    for x in range(N):
        if not visited_cols[x]:
            q = deque()
            q.append(x)
            visited_cols[x] = True
            component = []
            while q:
                node = q.popleft()
                component.append(node)
                for neighbor in adj_cols[node]:
                    if not visited_cols[neighbor]:
                        visited_cols[neighbor] = True
                        q.append(neighbor)
            col_components.append(component)

    # Compute result
    result = 1
    # Row components
    for comp in row_components:
        s = len(comp)
        fact = 1
        for i in range(1, s + 1):
            fact = fact * i % MOD
        result = result * fact % MOD
    # Column components
    for comp in col_components:
        s = len(comp)
        fact = 1
        for i in range(1, s + 1):
