        opp_list = opponents[i]
        for idx, j in enumerate(opp_list):
            if i < j:
                match = (i, j)
            else:
                match = (j, i)
            matches[i].append(match)
            pos[i][j] = idx

    # Build predecessors and graph
    predecessors = defaultdict(list)
