            if k > 0:
                prev_i = matches[i][k-1]
                predecessors[current_match].append(prev_i)
                adj[prev_i].append(current_match)
                in_degree[current_match] += 1
            # Process previous in j's sequence
            a, b = current_match
            # Determine j, the other player in the match
            if a == i:
                j = b
            else:
                j = a
            # Now, find the position of i in j's sequence
