        mask = (~r) & ((1 << 60) - 1)

        def f(n, m):
            if n < 0:
                return 0
            if m == 0:
                return 1
            highest_bit = m.bit_length() - 1
            if (1 << highest_bit) > n:
                return f(n, m & ((1 << highest_bit) - 1))
            lower_mask = m & ((1 << highest_bit) - 1)
            include = f(n - (1 << highest_bit), lower_mask)
            exclude = f(n, lower_mask)
            return include + exclude

        return f(b, mask) - f(a - 1, mask)

    total = 0
    for x in range(L, R + 1):
