        U = min(x - 1, R - x)
        if U < 1:
            continue
        if mask_x <= U:
            count = (1 << k) - 1
        else:
            count = 0
            from itertools import combinations
            for i in range(1, len(zero_bits) + 1):
                for subset in combinations(zero_bits, i):
                    r_val = 0
                    for bit in subset:
                        r_val |= (1 << bit)
                    if r_val <= U:
                        count += 1
        total += count
    total += (R - L + 1)
    print(total % MOD)

