        for mask in range(1 << m):
            sum_d = 0
            cost = 0
            for j in range(m):
                if mask & (1 << j):
                    sum_d += packages[j][0]
                    cost += packages[j][1]
            if sum_d in subsets:
                if cost < subsets[sum_d]:
                    subsets[sum_d] = cost
            else:
                subsets[sum_d] = cost
        return subsets

    left_subsets = generate_subsets(left_packages)
    right_subsets = generate_subsets(right_packages)

    min_total = float('inf')

    for sum1 in left_subsets:
        sum2_needed = -sum1
        if sum2_needed in right_subsets:
            total_cost = left_subsets[sum1] + right_subsets[sum2_needed]
            if sum1 == 0 and sum2_needed == 0:
                if total_cost == 0:
                    continue
            if total_cost < min_total:
                min_total = total_cost

