            for row in block:
                for j in range(W):
                    column_sums[j] += S[row][j]
            # Check if any column sum exceeds K
            for val in column_sums:
                if val > K:
                    valid = False
                    break
            if not valid:
                break
            # Compute vertical cuts for this block
            current_sum = 0
            vertical_cuts = 0
            for val in column_sums:
                if current_sum + val > K:
                    vertical_cuts += 1
                    current_sum = val
                else:
                    current_sum += val
            total_vertical_cuts += vertical_cuts

        if valid:
            total_cuts = total_vertical_cuts + (len(blocks) - 1)
