        grid.append([int(c) for c in line])

    min_cuts = float('inf')

    for bitmask in range(1 << (H-1)):
        row_groups = []
        current_group = [0]
        for split_point in range(H-1):
            if (bitmask >> split_point) & 1:
                row_groups.append(current_group)
                current_group = [split_point + 1]
        row_groups.append(current_group)

        row_sums = []
        for group in row_groups:
            sum_cols = [0] * W
            for row in group:
                for c in range(W):
                    sum_cols[c] += grid[row][c]
            row_sums.append(sum_cols)

        prefix_sums = []
        for sum_cols in row_sums:
            ps = [0] * W
            ps[0] = sum_cols[0]
            for c in range(1, W):
                ps[c] = ps[c-1] + sum_cols[c]
            prefix_sums.append(ps)

        current_start = 0
        vertical_segments = 0
        valid = True

        while current_start < W:
            max_ends = []
            for i in range(len(row_sums)):
                low = current_start
                high = W - 1
                best = current_start - 1
                while low <= high:
                    mid = (low + high) // 2
                    if current_start == 0:
                        s = prefix_sums[i][mid]
                    else:
                        s = prefix_sums[i][mid] - prefix_sums[i][current_start - 1]
                    if s <= K:
                        best = mid
                        low = mid + 1
                    else:
                        high = mid - 1
                max_ends.append(best)

