def main():
    H, W = map(int, sys.stdin.readline().split())
    grid = [sys.stdin.readline().strip() for _ in range(H)]

    road_squares = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                road_squares.append((i, j))

    max_distance = 0

    for start_i, start_j in road_squares:
        visited = [[-1 for _ in range(W)] for _ in range(H)]
        q = deque()
        q.append((start_i, start_j))
        visited[start_i][start_j] = 0
        current_max = 0

        while q:
            i, j = q.popleft()
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni = i + di
                nj = j + dj
                if 0 <= ni < H and 0 <= nj < W:
                    if grid[ni][nj] == '.' and visited[ni][nj] == -1:
                        visited[ni][nj] = visited[i][j] + 1
                        current_max = max(current_max, visited[ni][nj])
                        q.append((ni, nj))

        if current_max > max_distance:
            max_distance = current_max

    print(max_distance)

