        path = []
        while parent[x] != x:
            path.append(x)
            x = parent[x]
        root = x
        weights = [weight[node] for node in path]
        cumulative = [0] * len(weights)
        if len(weights) > 0:
            cumulative[-1] = weights[-1]
            for i in range(len(weights) - 2, -1, -1):
                cumulative[i] = (weights[i] + cumulative[i + 1]) % 2
        for i in range(len(path)):
            node = path[i]
            parent[node] = root
            weight[node] = cumulative[i]
        if path:
            return (root, cumulative[0])
        else:
            return (root, 0)

