class DSU:
    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.rank = [1] * (n + 1)
        self.parity = [0] * (n + 1)

    def find(self, x):
        path = []
        while self.parent[x] != x:
            path.append(x)
            x = self.parent[x]
        root = x
        current_parity = 0
        for node in reversed(path):
            new_parity = self.parity[node] ^ current_parity
            self.parent[node] = root
            self.parity[node] = new_parity
            current_parity = new_parity
        return (root, current_parity)

    def union(self, x, y, c):
        rx, px = self.find(x)
        ry, py = self.find(y)
        if rx == ry:
            return
        if self.rank[rx] < self.rank[ry]:
            rx, ry = ry, rx
            px, py = py, px
            x, y = y, x
        self.parent[ry] = rx
        self.parity[ry] = px ^ py ^ c
        if self.rank[rx] == self.rank[ry]:
            self.rank[rx] += 1

