import sys
from collections import defaultdict

MOD = 10**9 + 7

def is_forbidden(a, b, c, d):
    # Check if any of the swaps creates 'AGC'
    # Swap 0 and 1
    if (b == 'A' and a == 'G' and c == 'C') or (a == 'A' and c == 'G' and d == 'C'):
        return True
    # Swap 1 and 2
    if (a == 'A' and c == 'G' and b == 'C') or (c == 'A' and b == 'G' and d == 'C'):
        return True
    # Swap 2 and 3
    if (a == 'A' and b == 'G' and d == 'C') or (b == 'A' and d == 'G' and c == 'C'):
        return True
    return False

def main():
    N = int(sys.stdin.readline())
    dp = [defaultdict(int) for _ in range(N+1)]
    dp[0][()] = 1
    for i in range(1, N+1):
        for state in dp[i-1]:
            for c in ['A', 'C', 'G', 'T']:
                if len(state) == 3:
                    a, b, c_prev = state
                    new_state = (b, c_prev, c)
                    # Check if new_state is 'AGC'
                    if new_state == ('A', 'G', 'C'):
                        continue
                    # Check forbidden swaps
                    if is_forbidden(a, b, c_prev, c):
                        continue
                    dp[i][new_state] = (dp[i][new_state] + dp[i-1][state]) % MOD
                else:
                    new_state = list(state) + [c]
                    new_state = tuple(new_state)
                    # Check if new_state is 'AGC'
                    if len(new_state) == 3 and new_state == ('A', 'G', 'C'):
                        continue
                    # Check if any swap in new_state creates 'AGC'
                    if len(new_state) == 3:
                        # Check swap 0-1
                        if new_state[1] == 'A' and new_state[0] == 'G' and new_state[2] == 'C':
                            continue
                        # Check swap 1-2
                        if new_state[0] == 'A' and new_state[2] == 'G' and new_state[1] == 'C':
                            continue
                    dp[i][new_state] = (dp[i][new_state] + dp[i-1][state]) % MOD
    print(sum(dp[N].values()) % MOD)

