                new_state_list = list(state) + [new_char]
                if len(new_state_list) > 3:
                    new_state_list = new_state_list[1:]
                new_state = tuple(new_state_list)
                # Check if new_state is invalid (single case)
                if len(new_state) == 3:
                    if new_state in {(0, 2, 1), (2, 0, 1), (0, 1, 2)}:
                        continue
                # Check if previous state is of length 3 and four-character sequence is invalid
                if len(state) == 3:
                    a, b, c = state
                    d = new_char
                    # Condition 1: previous state is 'AGC'
