                    print(-1)
                    return

    # Prim's algorithm to find MST
    INF = float('inf')
    key = [INF] * n
    key[0] = 0
    visited = [False] * n
    total = 0

    for _ in range(n):
        # Find the minimum key node not yet visited
        u = -1
        min_key = INF
        for i in range(n):
            if not visited[i] and key[i] < min_key:
                min_key = key[i]
                u = i
        if u == -1:
            break
        visited[u] = True
        total += key[u]
        # Update key values for adjacent nodes
        for v in range(n):
            if not visited[v] and a[u][v] < key[v]:
                key[v] = a[u][v]

    print(total)

