                j += 1
            if j < N:
                swaps += (j - i)
                p[i], p[j] = p[j], p[i]
            else:
                if i + 1 < N:
                    swaps += 1
                    p[i], p[i+1] = p[i+1], p[i]
    if p[N-1] == N:
        swaps += 1
        p[N-1], p[N-2] = p[N-2], p[N-1]
    print(swaps)

