    N = int(input[0])
    s = list(map(int, input[1:N+1]))
    C = N - 1
    max_score = -float('inf')

    # Case 1: m*A - (m-1)*B = C
    for m in range(1, 2 * C + 1):
        if m == 1:
            max_score = max(max_score, 0)
            continue
        numerator = 1 - C
        denominator = m - 1
        lower_k = math.ceil(numerator / denominator)
        for k in range(lower_k, 0 + 1):
            A = C + k * (m - 1)
            B = C + m * k
            if A < 1 or B < 1 or A > C:
                continue
            steps = 2 * m - 1
            visited = set()
            valid = True
            for i in range(1, steps):
                pos = ((i + 1) // 2) * A - (i // 2) * B
                if pos < 0 or pos > C or pos in visited:
                    valid = False
                    break
                visited.add(pos)
            if not valid:
                continue
            score = 0
            for i in range(1, steps):
                pos = ((i + 1) // 2) * A - (i // 2) * B
                score += s[pos]
            max_score = max(max_score, score)

    # Case 2: m*(A - B) = C
    def get_divisors(n):
        divisors = set()
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
        return divisors

    divisors = get_divisors(C)
    for m in divisors:
        if m == 0:
            continue
        k = C // m
        for B in range(1, C - k + 1):
            A = B + k
            if A > C:
                continue
            steps = 2 * m
            visited = set()
