import bisect

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    K = int(data[1])
    A = list(map(int, data[2:2+N]))
    A.sort()

    # Find m: first index where A[m] >= 0
    m = bisect.bisect_left(A, 0)

    # Compute pos_count
    pos_count = [0] * N
    count = 0
    for i in range(N):
        if A[i] > 0:
            count += 1
        pos_count[i] = count
    total_pos = pos_count[-1]

    # Define count_pairs function
    def count_pairs(X):
        res = 0
        for i in range(N-1):
            if A[i] > 0:
                if X < 0:
                    continue
                # X >= 0
                target = X / A[i]
                left = i + 1
                right = N - 1
                best = i
                while left <= right:
                    mid = (left + right) // 2
                    if A[mid] <= target:
                        best = mid
                        left = mid + 1
                    else:
                        right = mid - 1
                res += best - i
            elif A[i] < 0:
                if X >= 0:
                    res += total_pos - pos_count[i]
                    a = -A[i]
                    target = X / a
                    start = max(i + 1, 0)
                    end = m - 1
                    if start > end:
                        continue
                    left = start
                    right = end
                    best_j = end + 1
                    while left <= right:
                        mid = (left + right) // 2
                        if A[mid] >= -target:
                            best_j = mid
                            right = mid - 1
                        else:
                            left = mid + 1
                    valid = max(0, end - best_j + 1)
                    res += valid
                else:
                    res += total_pos - pos_count[i]
            else:
                if X >= 0:
                    res += (N - 1 - i)
        return res

    # Binary search
    low = -10**18
    high = 10**18
    while low < high:
        mid = (low + high) // 2
        cnt = count_pairs(mid)
        if cnt < K:
            low = mid + 1
        else:
            high = mid
    print(low)

