    for i in range(N):
        if A[i] <= 0:
            neg_end = i
        else:
            break
    # Now, binary search
    low = -10**18
    high = 10**18
    answer = 0
    while low <= high:
        mid = (low + high) // 2
        # Compute count of pairs with product <= mid
        cnt = 0
        for i in range(N-1):
            if A[i] > 0:
                # case 1: A[i] is positive
                left = i + 1
                right = N - 1
                j = i + 1
                while left <= right:
                    m = (left + right) // 2
                    if A[i] * A[m] <= mid:
                        j = m
                        left = m + 1
                    else:
                        right = m - 1
                if j > i and A[i] * A[j] <= mid:
                    cnt += j - i
                else:
                    cnt += 0
            else:
                # A[i] is negative or zero
                if A[i] == 0:
                    # handle zero
                    if mid >= 0:
                        # case1: j in negative part (j >i and j <= neg_end)
                        # count all j in negative part
                        case1 = max(0, neg_end - i)
                        # case2: j in positive part
                        start_j = max(neg_end + 1, i + 1)
                        if start_j > N-1:
                            case2 = 0
                        else:
                            case2 = N - start_j
                        cnt += case1 + case2
                    else:
                        # mid < 0, no contribution
                        cnt += 0
                else:
                    # A[i] is negative
                    # case1: j in negative part
                    case1 = 0
                    if mid >= 0:
                        target = mid / A[i]
                        # find the first j in [i+1, neg_end] where A[j] >= target
                        # use bisect_left
                        pos = bisect.bisect_left(A, target, i+1, neg_end + 1)
                        case1 = max(0, neg_end - pos + 1)
                    else:
                        case1 = 0
                    # case2: j in positive part
                    case2 = 0
                    if mid >= 0:
                        start_j = max(neg_end + 1, i + 1)
                        if start_j > N-1:
                            case2 = 0
                        else:
                            case2 = N - start_j
                    else:
                        target = mid / A[i]
                        # target is mid / A[i], which is mid (negative) / A[i] (negative) → positive
                        pos = bisect.bisect_left(A, target, i+1, N)
                        case2 = max(0, N - pos)
                    cnt += case1 + case2
        if cnt >= K:
            answer = mid
            high = mid - 1
        else:
            low = mid + 1
    print(answer)

