            U_y.append(y)
        elif d == 'D':
            D_y.append(y)
        else:
            R_L_y.append(y)

    # Compute x part
    max_r_x = max(R_x) if R_x else None
    min_r_x = min(R_x) if R_x else None
    max_l_x = max(L_x) if L_x else None
    min_l_x = min(L_x) if L_x else None
    vertical_max_x = max(U_D_x) if U_D_x else None
    vertical_min_x = min(U_D_x) if U_D_x else None

