        if min_l_x is not None:
            x_min_terms.append(min_l_x - t)
        x_min = min(x_min_terms)
        # Compute y_max and y_min
        y_max_terms = []
        if horizontal_max_y is not None:
            y_max_terms.append(horizontal_max_y)
        if max_u_y is not None:
            y_max_terms.append(max_u_y + t)
        if max_d_y is not None:
            y_max_terms.append(max_d_y - t)
        y_max = max(y_max_terms)
        y_min_terms = []
        if horizontal_min_y is not None:
