        if min_u_y is not None:
            y_min_terms.append(min_u_y + t)
        if min_d_y is not None:
            y_min_terms.append(min_d_y - t)
        y_min = min(y_min_terms)
        current_area = (x_max - x_min) * (y_max - y_min)
        if current_area < min_val:
