    critical_times.add(0.0)

    times_list = sorted(critical_times)

    def compute_x_diff(t):
        x_max = -float('inf')
        if R_points:
            x_max = max(max_x_r + t, x_max)
        if L_points:
            x_max = max(max_x_l - t, x_max)
        if U_points or D_points:
            x_max = max(max_x_ud, x_max)
