            y_diff_prev = compute_y_diff(t_prev)
            y_diff_curr = compute_y_diff(t_curr)
            delta_t = t_curr - t_prev
            if delta_t == 0:
                continue
            a_x = (x_diff_curr - x_diff_prev) / delta_t
            a_y = (y_diff_curr - y_diff_prev) / delta_t
            b_x = x_diff_prev - a_x * t_prev
            b_y = y_diff_prev - a_y * t_prev
