        if current_area < min_area:
            min_area = current_area

    for i in range(len(sorted_times) - 1):
        t_low = sorted_times[i]
        t_high = sorted_times[i+1]
        if t_low == t_high:
            continue
        x_range_low = get_x_range(t_low)
        x_range_high = get_x_range(t_high)
        y_range_low = get_y_range(t_low)
        y_range_high = get_y_range(t_high)
        a_x = (x_range_high - x_range_low) / (t_high - t_low)
        b_x = x_range_low - a_x * t_low
        a_y = (y_range_high - y_range_low) / (t_high - t_low)
        b_y = y_range_low - a_y * t_low

        if a_x == 0 and a_y == 0:
            current_min = x_range_low * y_range_low
        elif a_x == 0:
            val_low = b_x * (a_y * t_low + b_y)
