        elif a_y == 0:
            val_low = (a_x * t_low + b_x) * b_y
            val_high = (a_x * t_high + b_x) * b_y
            current_min = min(val_low, val_high)
        else:
            numerator = -(a_x * b_y + a_y * b_x)
            denominator = 2 * a_x * a_y
            t_vertex = numerator / denominator
            if t_vertex < t_low:
                val_low = (a_x * t_low + b_x) * (a_y * t_low + b_y)
                val_high = (a_x * t_high + b_x) * (a_y * t_high + b_y)
                current_min = min(val_low, val_high)
            elif t_vertex > t_high:
                val_low = (a_x * t_low + b_x) * (a_y * t_low + b_y)
                val_high = (a_x * t_high + b_x) * (a_y * t_high + b_y)
                current_min = min(val_low, val_high)
            else:
                val_vertex = (a_x * t_vertex + b_x) * (a_y * t_vertex + b_y)
                val_low = (a_x * t_low + b_x) * (a_y * t_low + b_y)
                val_high = (a_x * t_high + b_x) * (a_y * t_high + b_y)
                current_min = min(val_vertex, val_low, val_high)
        if current_min < min_area:
            min_area = current_min

    print("{0:.10f}".format(min_area))

