            else:
                if j == W-1:
                    max_east[i][j] = 0
                else:
                    if grid[i][j+1] == '@':
                        max_east[i][j] = 0
                    else:
                        max_east[i][j] = 1 + max_east[i][j+1]

    max_west = [[0]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '@':
                max_west[i][j] = 0
            else:
                if j == 0:
                    max_west[i][j] = 0
                else:
                    if grid[i][j-1] == '@':
                        max_west[i][j] = 0
                    else:
                        max_west[i][j] = 1 + max_west[i][j-1]

