    K = int(input[ptr]); ptr +=1

    grid = [[0]*(C+1) for _ in range(R+1)]
    for _ in range(K):
        r = int(input[ptr]); ptr +=1
        c = int(input[ptr]); ptr +=1
        v = int(input[ptr]); ptr +=1
        grid[r][c] = v

    INF = float('-inf')
    prev_dp = [[INF]*4 for _ in range(C+1)]

    for i in range(1, R+1):
        curr_dp = [[INF]*4 for _ in range(C+1)]
        for j in range(1, C+1):
            if i == 1 and j == 1:
                if grid[i][j] > 0:
                    curr_dp[j][0] = 0
                    curr_dp[j][1] = grid[i][j]
                else:
                    curr_dp[j][0] = 0
                    curr_dp[j][1] = INF
            else:
                # Transition from up (i-1, j)
                if i > 1:
                    for k_prev in range(4):
                        if prev_dp[j][k_prev] != INF:
                            val = prev_dp[j][k_prev]
                            if grid[i][j] > 0:
                                curr_dp[j][1] = max(curr_dp[j][1], val + grid[i][j])
                                curr_dp[j][0] = max(curr_dp[j][0], val)
                            else:
                                curr_dp[j][0] = max(curr_dp[j][0], val)
