def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr]); ptr +=1
    M = int(input[ptr]); ptr +=1
    R = int(input[ptr]); ptr +=1
    r_list = list(map(int, input[ptr:ptr+R]))
    ptr += R

    INF = 10**18
    dist = [[INF]*(N+1) for _ in range(N+1)]
    for i in range(N+1):
        dist[i][i] = 0

    for _ in range(M):
        A = int(input[ptr]); ptr +=1
        B = int(input[ptr]); ptr +=1
        C = int(input[ptr]); ptr +=1
        if dist[A][B] > C:
            dist[A][B] = C
            dist[B][A] = C

    # Floyd-Warshall algorithm
    for k in range(1, N+1):
        for i in range(1, N+1):
            for j in range(1, N+1):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    min_total = INF
    for perm in itertools.permutations(r_list):
        total = 0
        for i in range(R-1):
            u = perm[i]
            v = perm[i+1]
            total += dist[u][v]
        if total < min_total:
            min_total = total
    print(min_total)

