    INF = 10**18
    # Initialize Floyd-Warshall
    dist = [[INF]*(N+1) for _ in range(N+1)]
    for i in range(1, N+1):
        dist[i][i] = 0
    for _ in range(M):
        A = int(input[ptr]); ptr +=1
        B = int(input[ptr]); ptr +=1
        C = int(input[ptr]); ptr +=1
        if dist[A][B] > C:
            dist[A][B] = C
        if dist[B][A] > C:
            dist[B][A] = C

    # Floyd-Warshall algorithm
    for k in range(1, N+1):
        for i in range(1, N+1):
            for j in range(1, N+1):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # TSP DP
    dp = [[INF]*R for _ in range(1 << R)]
    for i in range(R):
        mask = 1 << i
        dp[mask][i] = 0

    for mask in range(1 << R):
        for current in range(R):
            if not (mask & (1 << current)):
                continue
            for next_city in range(R):
                if mask & (1 << next_city):
                    continue
                new_mask = mask | (1 << next_city)
                new_cost = dp[mask][current] + dist[r_list[current]][r_list[next_city]]
                if new_cost < dp[new_mask][next_city]:
                    dp[new_mask][next_city] = new_cost

    full_mask = (1 << R) - 1
    ans = min(dp[full_mask][i] for i in range(R))
    print(ans)

