import sys
from collections import defaultdict
from math import gcd

MOD = 10**9 + 7

def normalize(a, b):
    if a == 0 and b == 0:
        return (0, 0)
    g = gcd(abs(a), abs(b))
    a //= g
    b //= g
    if a == 0:
        if b < 0:
            b = -b
    else:
        if a < 0:
            a = -a
            b = -b
    return (a, b)

def compute_path_sum(weights):
    n = len(weights)
    if n == 0:
        return 1
    dp0 = 1  # sum of independent sets where last node is not selected
    dp1 = 0  # sum where last node is selected
    for w in weights:
        new_dp0 = (dp0 + dp1) % MOD
        new_dp1 = (dp0 * w) % MOD
        dp0, dp1 = new_dp0, new_dp1
    return (dp0 + dp1) % MOD

def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = []
    B = []
    for i in range(N):
        a = int(data[1 + 2*i])
        b = int(data[2 + 2*i])
        A.append(a)
        B.append(b)

    groups = defaultdict(int)
    zero_count = 0
    for a, b in zip(A, B):
        if a == 0 and b == 0:
            zero_count += 1
        else:
            direction = normalize(a, b)
            groups[direction] += 1

    dir_to_perp = {}
    dir_to_group = {}
    for direction, count in groups.items():
        a, b = direction
        perp_a = -b
        perp_b = a
        perp_dir = normalize(perp_a, perp_b)
        dir_to_perp[direction] = perp_dir
        dir_to_group[direction] = count

    dir_to_perp_group = {}
    for direction in groups:
        perp_dir = dir_to_perp[direction]
        if perp_dir in groups:
            dir_to_perp_group[direction] = perp_dir
        else:
            dir_to_perp_group[direction] = None

    visited = set()
    total_ways = 1

    for direction in groups:
        if direction not in visited:
            path = []
            current_dir = direction
            while current_dir not in visited:
                visited.add(current_dir)
                path.append(current_dir)
                next_dir = dir_to_perp_group[current_dir]
                if next_dir is None:
                    break
                current_dir = next_dir
            if current_dir in path:
                index = path.index(current_dir)
                cycle = path[index:]
                chain = path[:index]
                # Process cycle
                cycle_weights = [dir_to_group[d] for d in cycle]
                m = len(cycle_weights)
                if m > 0:
                    P = compute_path_sum(cycle_weights)
                    if m == 2:
                        S = 0
                    else:
                        if m >= 4:
                            P_prev = compute_path_sum(cycle_weights[2:m-2])
                        else:
                            P_prev = 1
                        S = (cycle_weights[0] * cycle_weights[-1] * P_prev) % MOD
                    C = (P - S) % MOD
                    total_ways = (total_ways * C) % MOD
                # Process chain
                chain_weights = [dir_to_group[d] for d in chain]
                if len(chain_weights) > 0:
                    chain_sum = compute_path_sum(chain_weights)
                    total_ways = (total_ways * chain_sum) % MOD
            else:
                chain_weights = [dir_to_group[d] for d in path]
                if len(chain_weights) > 0:
                    chain_sum = compute_path_sum(chain_weights)
                    total_ways = (total_ways * chain_sum) % MOD

    if zero_count > 0:
        ans = (total_ways - 1 + zero_count) % MOD
    else:
        ans = (total_ways - 1) % MOD
    print(ans)

