from collections import deque

def main():
    K = int(sys.stdin.readline())
    max_val = 10**15
    queue = deque()
    for d in range(1, 10):
        queue.append(d)
    min_numbers = {}
    while queue:
        num = queue.popleft()
        s = sum(int(d) for d in str(num))
        if s not in min_numbers or num < min_numbers[s]:
            min_numbers[s] = num
        last_digit = int(str(num)[-1])
        for d in range(last_digit, 10):
            new_num = num * 10 + d
            if new_num <= max_val:
                queue.append(new_num)
    candidates = list(min_numbers.values())
    candidates.sort(key=lambda x: (x / sum(int(d) for d in str(x)), x))
    for i in range(K):
        print(candidates[i])

